INSERT INTO `glpi_knowbaseitemcategories` VALUES (3,0,0,0,'External','External','Public pages for customers with product guides and FAQs.',1,NULL,'[]','2026-08-20 08:09:24','2026-08-20 08:09:24'),(4,0,0,0,'Internal','Internal','Private pages for staff with workflows, training, and company policies',1,NULL,'[]','2026-08-20 08:09:39','2026-08-20 08:09:39'),(5,0,0,4,'Training materials','Internal > Training materials','Tools and content used to teach skills, share knowledge, or support learning',2,'{\"5\":5}','{\"4\":4}','2026-08-20 08:17:02','2026-08-20 08:10:44'),(6,0,0,4,'Standard operating procedures (SOPs)','Internal > Standard operating procedures (SOPs)','Daily workflows, escalation rules, and task checklists.',2,'{\"6\":6}','{\"4\":4}','2026-08-20 08:11:33','2026-08-20 08:11:29'),(7,0,0,4,'Onboarding guides','Internal > Onboarding guides','Step-by-step plan that helps new hires adjust to their new jobs, learn company rules, and feel welcome from day one',2,'{\"7\":7}','{\"4\":4}','2026-08-20 08:17:36','2026-08-20 08:11:49'),(8,0,0,4,'Internal FAQs','Internal > Internal FAQs','Private company document that centralizes answers to common employee questions about policies, tools, and processes.',2,'{\"8\":8}','{\"4\":4}','2026-08-20 08:18:16','2026-08-20 08:12:11'),(9,0,0,3,'Frequently Asked Questions (FAQs)','External > Frequently Asked Questions (FAQs)','',2,'{\"9\":9}','{\"3\":3}','2026-08-20 08:13:58','2026-08-20 08:13:58'),(10,0,0,3,'Product guides','External > Product guides','Tools or documents that help people choose, set up, and use items correctly',2,'{\"10\":10}','{\"3\":3}','2026-08-20 08:14:33','2026-08-20 08:14:33'),(11,0,0,3,'Troubleshooting steps','External > Troubleshooting steps','',2,'{\"11\":11}','{\"3\":3}','2026-08-20 08:19:01','2026-08-20 08:19:01'),(12,0,0,3,'Tutorials','External > Tutorials','',2,'{\"12\":12}','{\"3\":3}','2026-08-20 08:19:33','2026-08-20 08:19:33');
